# Initially generated by GitHub Copilot.
"""Render a JSON snippet as a BiDi-safe HTML <pre> block for authored docs.

The returned value is a raw-HTML htel (see mb_html.raw_html) containing a
<pre class="json-block"> element.  Hebrew-containing token spans get
``unicode-bidi:isolate; direction:rtl`` via the ``heb`` class, so the
browser treats each Hebrew fragment as an isolated RTL run within the
overall LTR JSON structure.
"""

import html as html_mod
import re

from pygments import lex
from pygments.lexers import JsonLexer
from pygments.lexers import PythonLexer
from pygments.token import Token

from mb_misc import mb_html

_VERIFY_ANY_MARKER_OBJECT_RE = re.compile(
    r'\{\s*"(?P<key>__verify_mp_any_[a-z_]+__)"\s*:\s*true\s*\}'
)
_VERIFY_ANY_MARKER_TOKEN_RE = re.compile(r'"__verify_mp_any_[a-z_]+__"')
_VERIFY_WILDCARD_STRING_OBJECT_RE = re.compile(
    r'\{\s*"__verify_mp_wildcard_string__"\s*:\s*(?P<value>"(?:\\.|[^"\\])*")\s*\}'
)


def json_block_raw_html(json_text: str):
    """Return a raw-HTML htel containing <pre class="json-block">...</pre>."""
    masked_json = _mask_verify_wildcards_for_display(json_text)
    return mb_html.raw_html(_build_pre_html(masked_json, JsonLexer()))


def python_block_raw_html(py_text: str):
    """Return a raw-HTML htel containing <pre class="json-block">...</pre>."""
    return mb_html.raw_html(_build_pre_html(py_text, PythonLexer()))


def json_block_with_notes_raw_html(json_text: str, notes: dict):
    """Return a raw-HTML htel with a line-numbered <pre> and a notes list.

    notes: dict mapping 1-based line numbers to plain-text annotation strings.
    """
    masked_json = _mask_verify_wildcards_for_display(json_text)
    pre_html = _build_pre_html(masked_json, JsonLexer(), with_line_nums=True)
    notes_html = _build_notes_html(notes)
    return mb_html.raw_html(pre_html + notes_html)


# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------


def _mask_verify_wildcards_for_display(json_text: str) -> str:
    """Mask internal verify wildcard markers before JSON display rendering."""

    def _replace_marker_object(match: re.Match[str]) -> str:
        key = match.group("key")
        if key == "__verify_mp_any_dict__":
            return "{...}"
        if key == "__verify_mp_any_list__":
            return "[...]"
        return "..."

    def _replace_wildcard_string_object(match: re.Match[str]) -> str:
        return match.group("value")

    masked = _VERIFY_ANY_MARKER_OBJECT_RE.sub(_replace_marker_object, json_text)
    masked = _VERIFY_WILDCARD_STRING_OBJECT_RE.sub(
        _replace_wildcard_string_object, masked
    )
    return _VERIFY_ANY_MARKER_TOKEN_RE.sub("...", masked)


def _token_color_class(ttype) -> str:
    if ttype is Token.Name.Tag:
        return "tok-key"
    if ttype in Token.Literal.String:
        return "tok-string"
    if ttype in Token.Literal.Number:
        return "tok-number"
    if ttype in Token.Keyword:
        return "tok-keyword"
    return "tok-punct"


def _has_hebrew(text: str) -> bool:
    return any("\u05d0" <= ch <= "\u05ea" or "\ufb1d" <= ch <= "\ufb4e" for ch in text)


def _has_pointing(text: str) -> bool:
    return any("\u0591" <= ch <= "\u05c7" for ch in text)


def _span(text: str, color_cls: str) -> str:
    escaped = html_mod.escape(text)
    classes = [color_cls]
    if _has_hebrew(text):
        classes.append("heb")
    if _has_pointing(text):
        classes.append("pointed")
    cls_attr = f' class="{" ".join(classes)}"'
    return f"<span{cls_attr}>{escaped}</span>"


def _split_by_newlines(tokens):
    """Split a Pygments token list into a list of per-line token lists.

    Newline characters are consumed (not included in the output tokens).
    Pygments typically appends a trailing newline; the resulting empty last
    line is dropped.
    """
    lines = [[]]
    for ttype, value in tokens:
        if "\n" in value:
            parts = value.split("\n")
            lines[-1].append((ttype, parts[0]))
            for part in parts[1:]:
                lines.append([(ttype, part)] if part else [])
        else:
            lines[-1].append((ttype, value))
    while lines and all(not v for _, v in lines[-1]):
        lines.pop()
    return lines


def _build_pre_html(code_text: str, lexer, with_line_nums: bool = False) -> str:
    lines_of_tokens = _split_by_newlines(list(lex(code_text, lexer)))
    width = len(str(len(lines_of_tokens)))
    line_htmls = []
    for i, line_tokens in enumerate(lines_of_tokens, 1):
        line_html = "".join(_span(v, _token_color_class(t)) for t, v in line_tokens)
        line_html = line_html.replace("...", '<span class="ellipsis">...</span>')
        if with_line_nums:
            ln = f'<span class="ln">{i:{width}d}</span>'
            line_html = ln + line_html
        line_htmls.append(line_html)
    code_html = "\n".join(line_htmls)
    return f'<pre class="json-block">{code_html}</pre>'


def _build_notes_html(notes: dict) -> str:
    items = "".join(
        f"<dt>Line {ln}</dt><dd>{html_mod.escape(text)}</dd>"
        for ln, text in sorted(notes.items())
    )
    return f'<dl class="json-notes">{items}</dl>'
